bemjson-to-decl Easy to use BEMJSON to set of BEM-entities (aka BEMDECL) converter written in JS Prerequisites Node.js 4.x+ Installing Run in your project: npm install --save bemjson-to-decl Usage const bemjsonToDecl = require ( 'bemjson-to-decl' ); bemjsonToDecl. convert ([ { elem : 'control' , elemMods : { theme : 'normal' }}, { elem : 'control' , elemMods : { theme : 'ghost' }} ], { block : 'button' }); // → // [ BemEntityName { block: 'button', elem: 'control' }, // BemEntityName { block: 'button', elem: 'control', mod: { name: 'theme', val: true } }, // BemEntityName { block: 'button', elem: 'control', mod: { name: 'theme', val: 'normal' } }, // BemEntityName { block: 'button', elem: 'control', mod: { name: 'theme', val: 'ghost' } } // ] API convert(bemjson: BEMJSON, scope: ?BemEntityName): BemEntityName[] Extract BEM-entities from BEMJSON object. const bemjsonToDecl = require ( 'bemjson-to-decl' ); bemjsonToDecl. convert ({ block : 'button' , mods : { theme : 'normal' }}); // → // [ BemEntityName { block: 'button' }, // BemEntityName { block: 'button', mod: { name: 'theme', val: true } }, // BemEntityName { block: 'button', mod: { name: 'theme', val: 'normal' } } // ] stringify(bemjson: BEMJSON, scope: ?BemEntityName, opts: ?{indent: string}): string Extract BEM-entities and stringify result to the string. const bemjsonToDecl = require ( 'bemjson-to-decl' ); bemjsonToDecl. stringify ({ block : 'button' }, null , { indent : '	' }); // → // "[
	{
		block: 'button'
	}
